def get_subject_from_token(token):
     try:
         payload = jwt.decode(token, verify=False)
         return payload.get('sub')  # 'sub' is the standard JWT claim for the subject
     except jwt.DecodeError:
         raise ValueError(f"Invalid JWT token: {token}")

def process_input(input_stream, rule_set, input_encoding):
     if isinstance(input_stream, str):
         # If input stream is a string, convert it to bytes
         input_stream = input_stream.encode(input_encoding)

     # Create a regex object for each rule in the rule set
     rule_objects = []
     for rule in rule_set:
         rule_objects.append(re.compile(rule))

     # Process the input stream against the rules
     processed_stream = []
     for match in itertools.chain(*[rule.finditer(input_stream) for rule in rule_objects]):
         processed_stream.append(match.group())

     # Convert the processed stream back to a string from bytes if necessary
     if input_encoding:
         processed_stream = [match.decode(input_encoding) for match in processed_stream]

     return processed_stream

def url_path_segment_escaper(): # Create a set of characters that should be escaped safe_characters = set("-_.~")
# Create a mapping of characters to their corresponding escaped representations escape_map = { chr(c): f"%{c:02x}" for c in range(128) if c not in safe_characters }
# Create an instance of the URL Percent Encoder encoder = urllib.parse.urlencode({"%": "%25"})
def escape_string(string): """Escapes the given string for inclusion in URL path segments.""" # Escape all non-ASCII characters escaped_string = encoder.encode(string).decode("utf-8")
# Escape special characters like "-", "_", ".", "~" for character, escaped_representation in escape_map.items(): escaped_string = escaped_string.replace(character, escaped_representation)
return escaped_string
return escape_string

